-- EDUNEXUS Knowledge Corpus + Curriculum Expansion v1
-- Idempotent seed. Source metadata is registered; this migration does NOT claim full-text ingestion or vector indexing.
BEGIN;

INSERT INTO public.knowledge_source_registry
(source_id,title,publisher,canonical_url,domain,trust_tier,intended_use,license_notes,agent_roles,editorial_summary,registry_version,ingestion_status,last_verified_at,created_at,updated_at)
VALUES
('unesco-genai-education-guidance','Guidance for Generative AI in Education and Research','UNESCO','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research','unesco.org','A','Human-centred AI education policy, privacy, age-appropriate design, and educator review','Use for policy synthesis and citation; do not reproduce substantial text without checking publication terms.','safety-privacy-evaluation,learning-designer,mentor-assistant','UNESCO guidance advocates human-centred and age-appropriate educational AI, data privacy protections, and pedagogically validated use.','2026-10-v1','metadata_registered',now(),now(),now()),
('unesco-ai-competency-students','AI Competency Framework for Students','UNESCO','https://www.unesco.org/en/articles/ai-competency-framework-students','unesco.org','A','AI literacy curriculum objectives across human-centred mindset, ethics, techniques and system design','Use framework metadata and paraphrased learning objectives with attribution; verify publication terms before reproducing tables.','learning-designer,hard-skill-tutor,assessment-rubric,safety-privacy-evaluation','Framework describes 12 competencies across four dimensions and progression from understand to apply to create.','2026-10-v1','metadata_registered',now(),now(),now()),
('esco-skills-api','ESCO Classification and Web Service API','European Commission','https://esco.ec.europa.eu/en/use-esco/use-esco-services-api/esco.europa.eu','esco.ec.europa.eu','A','Multilingual skill and occupation taxonomy, career mapping, skill synonyms','Follow ESCO API and dataset licensing/version requirements; store source version and attribution.','knowledge-steward,career-intelligence,development-mastery','ESCO provides interoperable classifications of skills, competences, qualifications and occupations for applications including career guidance and skills intelligence.','2026-10-v1','metadata_registered',now(),now(),now()),
('onet-database','O*NET Database','National Center for O*NET Development','https://www.onetcenter.org/database.html','onetcenter.org','A','Occupational skills, abilities, work activities and job context','Check current database license/attribution and version before importing bulk records.','career-intelligence,knowledge-steward,development-mastery','O*NET provides structured occupational information useful for mapping observable work skills and career pathways.','2026-10-v1','metadata_registered',now(),now(),now()),
('digcomp-framework','Digital Competence Framework (DigComp)','European Commission Joint Research Centre','https://joint-research-centre.ec.europa.eu/digcomp/digcomp-framework_en','joint-research-centre.ec.europa.eu','A','Digital literacy learning outcomes and progression','Record edition and licensing for each reused artifact; use source links and avoid assuming every associated file has identical rights.','learning-designer,hard-skill-tutor,assessment-rubric','DigComp frames digital competence through information/data literacy, communication/collaboration, content creation, safety and problem solving.','2026-10-v1','metadata_registered',now(),now(),now()),
('mit-ocw','MIT OpenCourseWare','Massachusetts Institute of Technology','https://ocw.mit.edu/','ocw.mit.edu','A','Discover open course structures, syllabi, assignments and discipline maps','Many OCW materials are CC BY-NC-SA; verify the license on each course page and retain attribution. Not suitable for commercial reuse without permission.','knowledge-steward,learning-designer,hard-skill-tutor','MIT OCW publishes course materials and learning activities; course-specific rights and license attribution must be retained.','2026-10-v1','metadata_registered',now(),now(),now()),
('oer-commons','OER Commons','Institute for the Study of Knowledge Management in Education','https://www.oercommons.org/','oercommons.org','B','Discover openly licensed teaching and learning resources','Only reuse items whose individual license explicitly permits the intended use; free-to-read is not automatically open.','knowledge-steward,learning-designer','OER Commons aggregates resources with metadata for level, subject and material type; each resource requires its own rights review.','2026-10-v1','metadata_registered',now(),now(),now()),
('openlearn-courses','OpenLearn Free Courses','The Open University','https://www.open.edu/openlearn/free-courses','open.edu','B','Course outcomes, study skills, employability and lifelong learning discovery','Many OU-owned materials are CC BY-NC-SA; page-specific restrictions and acknowledgements apply. Non-commercial terms can prohibit paid redistribution.','knowledge-steward,learning-designer,soft-skill-coach','OpenLearn provides free courses with stated outcomes and varied lengths; rights differ for third-party extracts and media.','2026-10-v1','metadata_registered',now(),now(),now()),
('openstax-license','OpenStax Textbooks Licensing','OpenStax / Rice University','https://help.openstax.org/s/article/Licensing-information-of-OpenStax-textbooks','openstax.org','A','Discover openly available textbook concepts and citation practice','CC BY-NC-SA 4.0; non-commercial only unless separate permission is granted; attribution and share-alike required.','knowledge-steward,hard-skill-tutor','OpenStax texts may be adapted for non-commercial use under attribution and share-alike conditions; avoid reuse in commercial offerings without permission.','2026-10-v1','metadata_registered',now(),now(),now()),
('khan-academy-terms','Khan Academy Terms and Content Use Guidance','Khan Academy','https://support.khanacademy.org/hc/en-us/articles/42929097425037-What-s-allowed-and-not-allowed-under-Khan-Academy-s-Terms-of-Service','khanacademy.org','A','Discovery links and license restrictions only; no scraping or content ingestion','Do not scrape, copy, commercially redistribute, or use its content/data to train AI; use links only unless explicit alternate license or permission applies.','safety-privacy-evaluation,knowledge-steward','Khan Academy terms restrict scraping and AI training on its content; EDUNEXUS stores only source metadata and discovery link.','2026-10-v1','metadata_registered',now(),now(),now()),
('oer-open-licensing','Introduction to Open Educational Resources and Usage Rights','OER Commons Help Center','https://help.oercommons.org/support/solutions/articles/42000046846-introduction-to-oer','help.oercommons.org','B','Rights-aware resource selection and license triage','Verify the license on each individual resource; do not infer reuse rights from free access alone.','knowledge-steward,safety-privacy-evaluation','OER requires explicit public-domain status or an open license allowing the intended access, reuse, adaptation and redistribution.','2026-10-v1','metadata_registered',now(),now(),now())
ON CONFLICT (source_id) DO UPDATE SET
 title=EXCLUDED.title,publisher=EXCLUDED.publisher,canonical_url=EXCLUDED.canonical_url,domain=EXCLUDED.domain,
 trust_tier=EXCLUDED.trust_tier,intended_use=EXCLUDED.intended_use,license_notes=EXCLUDED.license_notes,
 agent_roles=EXCLUDED.agent_roles,editorial_summary=EXCLUDED.editorial_summary,registry_version=EXCLUDED.registry_version,
 ingestion_status=EXCLUDED.ingestion_status,last_verified_at=now(),updated_at=now();

