ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,description=EXCLUDED.description,updated_at=now();

INSERT INTO public.skills(slug,name,domain,description)
VALUES
('literasi-ai-bertanggung-jawab','Literasi AI Bertanggung Jawab','hard_skill','Memahami keterbatasan AI, memeriksa keluaran, menjaga privasi, dan menggunakan AI secara bertanggung jawab.'),
('literasi-digital-keamanan','Literasi Digital dan Keamanan','hard_skill','Menilai sumber, melindungi akun dan data, serta mengenali risiko digital.'),
('berpikir-kritis-berbasis-bukti','Berpikir Kritis Berbasis Bukti','soft_skill','Membedakan fakta, inferensi, asumsi, dan ketidakpastian sebelum mengambil keputusan.'),
('kesiapan-karier','Kesiapan Karier','soft_skill','Menghubungkan keterampilan yang dapat dibuktikan dengan peran kerja dan rencana pengembangan.')
ON CONFLICT (slug) DO UPDATE SET name=EXCLUDED.name,domain=EXCLUDED.domain,description=EXCLUDED.description,updated_at=now();

INSERT INTO public.courses(program_id,name,slug,description)
SELECT p.id,v.name,v.slug,v.description FROM public.programs p
CROSS JOIN (VALUES
('Literasi Digital dan Evaluasi Informasi','literasi-digital-evaluasi-informasi','Menilai kredibilitas sumber, memeriksa klaim, memahami lisensi, dan mengelola informasi digital.'),
('Literasi AI dan Penggunaan AI yang Bertanggung Jawab','literasi-ai-bertanggung-jawab','Memahami batasan model AI, menulis instruksi yang jelas, memeriksa hasil, dan melindungi data.'),
('Keamanan Digital dan Privasi Pribadi','keamanan-digital-privasi','Praktik dasar keamanan akun, privasi, phishing, dan respons insiden untuk pembelajar.'),
('Kesiapan Karier dan Portofolio Keterampilan','kesiapan-karier-portofolio','Memetakan keterampilan terhadap peran, mengumpulkan bukti kerja, dan merencanakan pengembangan karier.')
) AS v(name,slug,description)
WHERE p.slug='literasi-digital-ai-karier'
ON CONFLICT (slug) DO UPDATE SET program_id=EXCLUDED.program_id,name=EXCLUDED.name,description=EXCLUDED.description,updated_at=now();

INSERT INTO public.modules(course_id,name,position)
SELECT c.id,v.name,v.position FROM public.courses c
JOIN (VALUES
('literasi-digital-evaluasi-informasi','Menilai Sumber dan Klaim',1),
('literasi-digital-evaluasi-informasi','Lisensi, Atribusi dan Sintesis',2),
('literasi-ai-bertanggung-jawab','Cara Kerja dan Batasan AI',1),
('literasi-ai-bertanggung-jawab','Prompt, Verifikasi dan Privasi',2),
('keamanan-digital-privasi','Perlindungan Akun dan Perangkat',1),
('keamanan-digital-privasi','Mengenali dan Menangani Ancaman',2),
('kesiapan-karier-portofolio','Pemetaan Keterampilan dan Peran',1),
('kesiapan-karier-portofolio','Portofolio dan Rencana Pengembangan',2)
) AS v(course_slug,name,position) ON c.slug=v.course_slug
ON CONFLICT (course_id,position) DO UPDATE SET name=EXCLUDED.name;

INSERT INTO public.lessons(module_id,title,content,position)
SELECT m.id,v.title,jsonb_build_object(
'summary',v.summary,
'objectives',jsonb_build_array(v.objective),
'sections',jsonb_build_array(jsonb_build_object('heading','Materi inti','body',v.body),jsonb_build_object('heading','Cara menerapkan','body',v.apply)),
'exercise',v.exercise,
'sources',v.sources
),v.lesson_position
FROM (VALUES
('literasi-digital-evaluasi-informasi',1,1,'Periksa Asal dan Kredibilitas Sumber','Kualitas keputusan bergantung pada asal, konteks, tanggal, dan bukti yang mendukung sebuah klaim.','Mengidentifikasi penerbit, tanggal, bukti, tujuan, dan keterbatasan sumber.','Periksa siapa penerbitnya, keahlian yang relevan, tanggal pembaruan, bukti yang ditautkan, dan apakah klaim dibedakan dari opini. Cari sumber primer dan konfirmasi klaim penting dari sumber independen. Popularitas dan posisi hasil pencarian bukan bukti kebenaran.','Buat tabel klaim, sumber, bukti pendukung, bukti yang berlawanan, tanggal, dan tingkat keyakinan.','Pilih satu klaim publik dan cari sumber primer serta satu sumber independen. Catat apa yang belum dapat dipastikan.','https://help.oercommons.org/support/solutions/articles/42000046846-introduction-to-oer'),
('literasi-digital-evaluasi-informasi',1,2,'Fakta, Inferensi dan Ketidakpastian','Pernyataan fakta, interpretasi, dan prediksi perlu dibedakan agar tidak membuat kesimpulan berlebihan.','Memisahkan observasi yang dapat diverifikasi dari inferensi dan asumsi.','Fakta dapat diperiksa pada sumber; inferensi adalah kesimpulan dari fakta; asumsi adalah premis yang belum diuji; prediksi menyatakan kemungkinan masa depan. Tulis apa yang diketahui, apa yang diduga, dan bukti tambahan apa yang dapat mengubah kesimpulan.','Gunakan label FAKTA, INFERENSI, ASUMSI, dan BELUM DIKETAHUI pada ringkasan analisis.','Ambil berita atau laporan publik dan tandai tiga kalimat berdasarkan empat kategori tersebut. Jelaskan alasan klasifikasi.','https://joint-research-centre.ec.europa.eu/digcomp/digcomp-framework_en'),
('literasi-digital-evaluasi-informasi',2,1,'Lisensi Konten dan Atribusi','Konten yang dapat dibaca gratis belum tentu boleh disalin, diubah, dilatih ke AI, atau dijual kembali.','Memeriksa izin penggunaan, atribusi, larangan komersial, dan kewajiban berbagi serupa.','Periksa lisensi spesifik pada setiap sumber dan aset. CC BY umumnya mewajibkan atribusi; CC BY-SA juga mewajibkan lisensi serupa; NC membatasi penggunaan komersial; ND membatasi distribusi adaptasi. Syarat dapat berbeda untuk gambar, kutipan, dan konten pihak ketiga.','Simpan judul, pencipta, URL, lisensi, versi/tanggal akses, perubahan yang dibuat, dan cara atribusi.','Tinjau tiga sumber pembelajaran dan tentukan apakah boleh disalin, diterjemahkan, dipakai komersial, atau hanya ditautkan.','https://help.oercommons.org/support/solutions/articles/42000046845-usage-rights'),
('literasi-digital-evaluasi-informasi',2,2,'Menyusun Ringkasan dengan Jejak Sumber','Sintesis yang baik menggabungkan beberapa sumber tanpa menghilangkan asal klaim atau perbedaan pandangan.','Membuat ringkasan singkat yang dapat ditelusuri kembali ke sumber aslinya.','Susun pertanyaan, pilih sumber primer dan pendukung, catat klaim per sumber, bandingkan kesesuaian dan perbedaan, lalu tulis kesimpulan dengan tautan. Jangan menyebut sebuah sumber telah diindeks atau ditelaah penuh jika hanya metadata yang diperiksa.','Tautkan setiap klaim penting ke sumber, tanggal akses, dan tingkat kepercayaan; simpan catatan lisensi secara terpisah.','Buat ringkasan 150 kata dari dua sumber publik, sertakan tautan, dan tulis satu hal yang masih belum diketahui.','https://www.oercommons.org/'),
('literasi-ai-bertanggung-jawab',1,1,'Apa yang Dapat dan Tidak Dapat Dilakukan AI Generatif','Model generatif menghasilkan respons berdasarkan pola yang dipelajari dan dapat menghasilkan kesalahan yang terdengar meyakinkan.','Menjelaskan keluaran probabilistik, keterbatasan konteks, dan kebutuhan verifikasi manusia.','AI dapat membantu membuat draf, menjelaskan konsep, mengelompokkan informasi, dan mengusulkan opsi. AI dapat salah mengutip, mengarang fakta, melewatkan konteks, atau merefleksikan bias. Untuk keputusan penting, periksa sumber primer dan gunakan penilaian manusia.','Perlakukan jawaban AI sebagai hipotesis awal, bukan sumber otoritatif. Minta rujukan yang dapat diperiksa dan buka sumbernya.','Uji satu jawaban AI dengan dua sumber primer; tandai pernyataan yang didukung, tidak didukung, dan keliru.','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research'),
('literasi-ai-bertanggung-jawab',1,2,'AI yang Berpusat pada Manusia dan Etika','Penerapan AI pendidikan harus mendukung pembelajar, menjaga privasi, dan memungkinkan pengawasan manusia.','Mengenali isu privasi, bias, transparansi, aksesibilitas, dan kesesuaian usia.','Jangan masukkan data pribadi, rahasia, atau catatan siswa yang dapat diidentifikasi ke layanan tanpa otorisasi dan dasar yang sah. Jelaskan kapan AI digunakan, sediakan cara meminta tinjauan manusia, dan hindari inferensi sensitif tentang emosi atau kepribadian dari video.','Gunakan data sintetis atau dianonimkan saat menguji; batasi retensi dan akses; dokumentasikan tujuan dan risiko.','Rancang daftar pemeriksaan sebelum sekolah menggunakan tutor AI: data, usia, akurasi, pengawasan, aksesibilitas, dan mekanisme keluhan.','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research'),
('literasi-ai-bertanggung-jawab',2,1,'Menulis Prompt yang Terukur','Instruksi yang baik menyebut tujuan, konteks yang aman, format keluaran, batasan, dan kriteria keberhasilan.','Membuat prompt yang jelas serta dapat dievaluasi dan direvisi.','Berikan peran fungsional tanpa memberi otoritas palsu; sertakan konteks seperlunya, tugas, format, batasan, contoh jika berguna, dan cara menangani ketidakpastian. Hindari menyertakan data rahasia. Pecah tugas kompleks menjadi tahap yang dapat diperiksa.','Minta model menandai asumsi dan pertanyaan klarifikasi sebelum menjawab ketika informasi penting tidak tersedia.','Tulis prompt untuk menjelaskan konsep kepada pemula, dengan tujuan belajar, contoh, kuis formatif, dan aturan untuk menyatakan ketidakpastian.','https://www.unesco.org/en/articles/ai-competency-framework-students'),
('literasi-ai-bertanggung-jawab',2,2,'Verifikasi Keluaran AI dan Referensi','Keluaran AI perlu diperiksa dari sisi fakta, perhitungan, sumber, bias, dan kesesuaian tugas.','Melakukan pemeriksaan silang dan mengoreksi keluaran tanpa menyembunyikan ketidakpastian.','Verifikasi angka dengan perhitungan independen; buka setiap URL; pastikan sumber benar-benar mendukung klaim; periksa tanggal dan konteks; minta perspektif alternatif. Jangan menganggap sumber yang disebut AI otomatis ada atau relevan.','Simpan prompt, versi model bila tersedia, sumber yang diperiksa, koreksi, dan keputusan manusia untuk tugas berisiko tinggi.','Audit satu teks AI dan buat daftar klaim beserta sumber pendukung, tingkat kepastian, serta koreksi.','https://www.unesco.org/en/articles/ai-competency-framework-students'),
('keamanan-digital-privasi',1,1,'Kata Sandi, MFA dan Pemulihan Akun','Akun yang aman mengurangi risiko pengambilalihan dan kebocoran data.','Mempraktikkan kata sandi unik, autentikasi multifaktor, dan pemulihan akun yang aman.','Gunakan pengelola kata sandi untuk membuat kata sandi unik dan panjang. Aktifkan MFA atau passkey bila tersedia. Simpan kode pemulihan di tempat aman. Jangan membagikan kode OTP atau menyetujui permintaan login yang tidak dimulai sendiri.','Amankan email utama terlebih dahulu karena email sering menjadi jalur pemulihan untuk akun lain.','Buat daftar periksa keamanan akun tanpa mencatat atau membagikan kata sandi aktual.','https://www.cisa.gov/secure-our-world'),
('keamanan-digital-privasi',1,2,'Phishing dan Rekayasa Sosial','Serangan sering memanfaatkan urgensi, otoritas palsu, rasa takut, atau hadiah untuk memicu tindakan cepat.','Mengenali indikator pesan berbahaya dan memverifikasi permintaan melalui kanal terpisah.','Periksa domain secara hati-hati, konteks, lampiran, tautan, dan permintaan rahasia. Jangan mengandalkan logo atau nama pengirim saja. Jika ada permintaan pembayaran atau kredensial, konfirmasi melalui kontak yang sudah dikenal, bukan nomor di pesan.','Laporkan pesan mencurigakan melalui kanal organisasi; jangan meneruskan tautan berbahaya kepada rekan.','Nilai tiga contoh pesan sintetis dan jelaskan indikator yang membuatnya layak diperiksa lebih lanjut.','https://www.cisa.gov/secure-our-world'),
('keamanan-digital-privasi',2,1,'Minimisasi Data dan Privasi','Mengumpulkan data yang tidak diperlukan memperbesar risiko bagi pengguna dan organisasi.','Menentukan data minimum, tujuan pemrosesan, akses, dan masa simpan.','Kumpulkan hanya data yang diperlukan untuk tujuan yang jelas. Batasi akses berdasarkan peran, tetapkan masa simpan, sediakan mekanisme koreksi/penghapusan sesuai kewajiban, dan jangan menganggap pseudonimisasi selalu menghilangkan risiko identifikasi.','Gunakan data contoh untuk pengembangan dan uji kebijakan retensi serta kontrol akses.','Gambar alur data untuk sebuah kuis daring; tandai data yang benar-benar diperlukan, siapa yang mengakses, dan kapan data dihapus.','https://www.unesco.org/en/articles/guidance-generative-ai-education-and-research'),
('keamanan-digital-privasi',2,2,'Respons Awal Saat Insiden','Respons terstruktur membantu membatasi dampak insiden tanpa merusak bukti.','Mengetahui cara melapor, membatasi paparan, dan mendokumentasikan fakta awal.','Hentikan interaksi dengan pesan mencurigakan, laporkan ke pengelola yang tepat, gunakan perangkat atau kanal tepercaya untuk mengganti kredensial jika diperlukan, dan ikuti prosedur organisasi. Jangan menghapus bukti penting atau menyelidiki di luar kewenangan.','Catat waktu, sistem terdampak, tindakan yang sudah dilakukan, dan indikator yang teramati tanpa menyebarkan data sensitif.','Buat runbook satu halaman untuk akun belajar yang diduga diambil alih, termasuk jalur eskalasi dan perlindungan data.','https://www.cisa.gov/secure-our-world'),
('kesiapan-karier-portofolio',1,1,'Peta Keterampilan ke Peran Kerja','Kerangka keterampilan dan taksonomi pekerjaan membantu menemukan kesenjangan belajar, tetapi bukan jaminan kelayakan kerja.','Menghubungkan keterampilan yang dapat diamati dengan tugas dan peran pekerjaan.','Gunakan deskripsi pekerjaan dan taksonomi seperti ESCO atau O*NET sebagai titik awal. Bandingkan tugas, keterampilan, tingkat kemahiran, dan konteks. Periksa relevansi lokal dan tanggal pembaruan; nama keterampilan yang sama dapat memiliki definisi berbeda.','Buat matriks peran, tugas, keterampilan, bukti yang dimiliki, dan langkah belajar berikutnya.','Pilih satu peran pekerjaan dan identifikasi lima keterampilan yang diminta serta bukti nyata untuk menunjukkan tiap keterampilan.','https://esco.ec.europa.eu/en/use-esco/use-esco-services-api'),
('kesiapan-karier-portofolio',1,2,'Membaca Deskripsi Pekerjaan Secara Kritis','Persyaratan pekerjaan dapat mencampur keterampilan inti, preferensi, dan syarat formal.','Memisahkan persyaratan wajib, nilai tambah, dan bukti yang dapat ditunjukkan.','Kelompokkan persyaratan berdasarkan tugas dan hasil kerja, bukan hanya kata kunci. Bedakan kualifikasi formal, pengalaman, alat, perilaku kerja, dan preferensi. Jangan menyimpulkan bahwa seseorang tidak mampu hanya karena tidak memiliki istilah tertentu di CV.','Gunakan beberapa lowongan untuk menemukan pola keterampilan berulang, lalu verifikasi dengan sumber okupasi resmi.','Bandingkan tiga deskripsi untuk peran serupa dan buat daftar keterampilan yang berulang serta keterampilan khusus perusahaan.','https://www.onetcenter.org/database.html'),
('kesiapan-karier-portofolio',2,1,'Membangun Portofolio Berbasis Bukti','Portofolio yang kuat menunjukkan konteks, kontribusi, proses, hasil, dan batasan pekerjaan.','Menyusun bukti kerja yang dapat ditinjau tanpa membocorkan informasi rahasia.','Untuk tiap artefak jelaskan masalah, peran pribadi, proses, hasil terukur, umpan balik, dan hal yang dipelajari. Hilangkan data pelanggan, kode rahasia, identitas siswa, dan materi milik pemberi kerja yang tidak boleh dibagikan.','Pilih bukti yang relevan dengan keterampilan target dan jelaskan bagian yang benar-benar dikerjakan sendiri.','Buat deskripsi portofolio satu halaman untuk proyek simulasi, termasuk tujuan, proses, hasil, keterbatasan, dan bukti.','https://www.onetcenter.org/database.html'),
('kesiapan-karier-portofolio',2,2,'Rencana Pengembangan 30 Hari','Rencana yang realistis menetapkan tujuan, latihan, bukti, dan tinjauan berkala.','Menetapkan target belajar yang terukur dan menyesuaikan rencana berdasarkan hasil.','Pilih satu atau dua keterampilan prioritas berdasarkan kebutuhan peran dan kesenjangan bukti. Tetapkan latihan mingguan, hasil yang dapat ditinjau, kriteria rubrik, serta waktu refleksi. Gunakan umpan balik untuk memperbarui target, bukan sekadar menghitung waktu belajar.','Tentukan ukuran keberhasilan yang menunjukkan perilaku atau hasil nyata, bukan hanya kehadiran atau rasa percaya diri.','Buat rencana empat minggu dengan satu hasil kerja setiap minggu dan rubrik sederhana untuk menilainya.','https://esco.ec.europa.eu/en/use-esco/use-esco-services-api')
) AS v(course_slug,module_position,lesson_position,title,summary,objective,body,apply,exercise,sources)
JOIN public.courses c ON c.slug=v.course_slug
JOIN public.modules m ON m.course_id=c.id AND m.position=v.module_position
ON CONFLICT (module_id,position) DO UPDATE SET title=EXCLUDED.title,content=EXCLUDED.content;

COMMIT;
